const item = $input.first().json;
const raw = item.output || '';

if (!raw) {
  return [{ json: {
    name: '', currentRole: '', yearsExperience: 0, field: '',
    primarySkills: [], secondarySkills: [], education: '',
    certifications: [], expectedSalary: null, preferredLocation: null,
    remotePreference: null,
    summary: 'NODE ERROR - Gemini call failed after retries: ' + JSON.stringify(item.error || item).slice(0, 300)
  }}];
}

const cleaned = raw.replace(/```json|```/g, '').trim();
let profile;
try {
  profile = JSON.parse(cleaned);
} catch (e) {
  profile = {
    name: '', currentRole: '', yearsExperience: 0, field: '',
    primarySkills: [], secondarySkills: [], education: '',
    certifications: [], expectedSalary: null, preferredLocation: null,
    remotePreference: null,
    summary: 'PARSE ERROR - raw AI output: ' + raw.slice(0, 300)
  };
}

profile.fileName = ($('Download CV 1 (Google Drive)').first().binary && $('Download CV 1 (Google Drive)').first().binary.data && $('Download CV 1 (Google Drive)').first().binary.data.fileName) || 'CV 1';

return [{ json: profile }];

const item = $input.first().json;
const raw = item.output || '';
const job = $('Loop Over Jobs').item.json;
const analyzedDate = new Date().toISOString().slice(0, 10);

let result;

if (!raw) {
  result = {
    rank: 0, shouldApply: 'Error', domainMatch: 'Error',
    whyFit: 'Node error - see Errors sheet for details',
    blockingGaps: '', learnableGaps: '', salaryRecommendation: '',
    salaryReasoning: 'NODE ERROR after retries: ' + JSON.stringify(item.error || item).slice(0, 500)
  };
} else {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  try {
    result = JSON.parse(cleaned);
  } catch (e) {
    result = {
      rank: 0, shouldApply: 'Error', domainMatch: 'Error',
      whyFit: 'AI returned invalid JSON - see Errors sheet for details',
      blockingGaps: '', learnableGaps: '', salaryRecommendation: '',
      salaryReasoning: 'PARSE ERROR raw output: ' + raw.slice(0, 500)
    };
  }
}

return [{ json: { ...job, ...result, analyzedDate } }];

